import unittest
from tech_connector.recovery import Recoverer
from tech_connector.scheduler import Scheduler
from tech_connector.worker import Worker


class TestScheduler(unittest.TestCase):

    def setUp(self):
        from tech_connector.journal import Journal
        self.journal = Journal('path/to/test_journal.jsonl')
        self.scheduler = Scheduler(self.journal)
        self.worker = Worker(self.journal)

    def test_cycle_detection(self):
        self.scheduler.add_task('task1', ['task2'])
        self.scheduler.add_task('task2', ['task3'])
        self.scheduler.add_task('task3', ['task1'])
        with self.assertRaises(ValueError):
            self.scheduler.schedule()

    def test_deterministic_topological_scheduling(self):
        self.scheduler.add_task('task1', [])
        self.scheduler.add_task('task2', ['task1'])
        self.scheduler.add_task('task3', ['task1'])
        self.scheduler.schedule()
        expected_order = ['task1', 'task2', 'task3']
        self.assertEqual(self.scheduler.topological_order, expected_order)

